final class Worker implements Runnable {
    private volatile boolean stopping;              // phase-1 latch
    void shutdown() { stopping = true; }            // idempotent

    public void run() {
        try {
            while (!stopping) workOnce();           // safe point
        } finally {
            flushAndRelease();                      // phase 2
        }
    }
}
